USE arqueologia_ucb;
START TRANSACTION;

















COMMIT;

-- Verificação dos volumes exigidos.
SELECT 'instituicao' AS tabela, COUNT(*) AS registros FROM instituicao
UNION ALL SELECT 'pesquisador', COUNT(*) FROM pesquisador
UNION ALL SELECT 'sitio_arqueologico', COUNT(*) FROM sitio_arqueologico
UNION ALL SELECT 'campanha', COUNT(*) FROM campanha
UNION ALL SELECT 'participacao_campanha', COUNT(*) FROM participacao_campanha
UNION ALL SELECT 'unidade_escavacao', COUNT(*) FROM unidade_escavacao
UNION ALL SELECT 'artefato', COUNT(*) FROM artefato
UNION ALL SELECT 'fragmento', COUNT(*) FROM fragmento
UNION ALL SELECT 'artefato_analise', COUNT(*) FROM artefato_analise
UNION ALL SELECT 'custodia_artefato', COUNT(*) FROM custodia_artefato;
